WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/32.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/32.0/apex.js")} 

var record = new sforce.SObject("Inventory__c"); 
var result = sforce.apex.execute('SDUnblockUnit', 'chkAccess',{objID: "{!Inventory__c.Id}"}); 
if(result == 'Error1'){ 
alert('You are not authorized to unblock this Unit.'); 
}
else if(result == 'Error2'){
alert('You can release only Salesforce Block or Sales Director Block or Sales Consultant Block Units.');
}
else if(result == 'Success'){
alert('Successfully released this unit.');
location.reload();
}
else if(result == 'MovedBackSuccessfully'){
alert('Unit moved back Salesforce block Successfully.');
location.reload();
}
